/* ===== Reset & Base ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'Helvetica Neue', Helvetica, Arial, sans-serif;
  color: #1d1d1f;
  background: #fff;
  line-height: 1.47;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
a { color: #0066cc; text-decoration: none; }
a:hover { text-decoration: underline; }
ul, ol { list-style: none; }
img { max-width: 100%; display: block; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }

/* ===== Top Nav ===== */
.top-nav {
  background: rgba(29,29,31,.92);
  backdrop-filter: saturate(180%) blur(20px);
  position: sticky; top: 0; z-index: 1000;
  height: 48px;
  display: flex; align-items: center; justify-content: center;
}
.top-nav-inner {
  max-width: 1024px; width: 100%;
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 22px;
}
.top-nav a { color: #d1d1d6; font-size: 12px; letter-spacing: -.01em; transition: color .3s; }
.top-nav a:hover { color: #fff; text-decoration: none; }
.top-nav .nav-logo { font-size: 17px; font-weight: 600; color: #d1d1d6; }
.top-nav .nav-links { display: flex; gap: 24px; }

/* ===== Ribbon Banner ===== */
.ribbon-banner {
  background: #f5f5f7;
  text-align: center;
  padding: 12px 20px;
  font-size: 14px;
  color: #1d1d1f;
  border-bottom: 1px solid #d2d2d7;
}
.ribbon-banner a { color: #0066cc; font-weight: 500; }

/* ===== Section ===== */
.section {
  padding: 60px 0;
  overflow: hidden;
}
.section-dark { background: #000; color: #f5f5f7; }
.section-light { background: #f5f5f7; }
.section-white { background: #fff; }
.section-header {
  text-align: center;
  max-width: 680px;
  margin: 0 auto 40px;
  padding: 0 20px;
}
.section-header h2 {
  font-size: 48px; font-weight: 700; letter-spacing: -.015em; line-height: 1.08;
}
.section-header p {
  font-size: 21px; color: #6e6e73; margin-top: 8px; font-weight: 400;
}
.section-dark .section-header p { color: #a1a1a6; }

/* ===== Hero ===== */
.hero {
  text-align: center;
  padding: 80px 20px 60px;
  background: #f5f5f7;
}
.hero h1 {
  font-size: 56px; font-weight: 700; letter-spacing: -.02em; line-height: 1.05;
}
.hero p {
  font-size: 28px; color: #6e6e73; margin-top: 8px; font-weight: 400;
}
.hero-ctas { margin-top: 20px; display: flex; gap: 20px; justify-content: center; flex-wrap: wrap; }

/* ===== CTAs ===== */
.cta-primary {
  display: inline-block;
  background: #0071e3;
  color: #fff !important;
  font-size: 17px; font-weight: 400;
  padding: 8px 22px;
  border-radius: 980px;
  transition: background .3s;
  text-decoration: none !important;
}
.cta-primary:hover { background: #0077ed; text-decoration: none !important; }
.cta-secondary {
  display: inline-block;
  color: #0066cc;
  font-size: 21px; font-weight: 400;
  transition: color .3s;
}
.cta-secondary:hover { text-decoration: underline; }
.cta-link { font-size: 17px; color: #0066cc; }
.cta-link::after { content: ' >'; }

/* ===== Product Grid (Homepage) ===== */
.product-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  max-width: 1024px;
  margin: 0 auto;
  padding: 0 20px;
}
.product-tile {
  position: relative;
  border-radius: 20px;
  overflow: hidden;
  text-align: center;
  padding: 44px 30px 0;
  min-height: 500px;
  display: flex;
  flex-direction: column;
  align-items: center;
}
.product-tile.dark { background: #000; color: #f5f5f7; }
.product-tile.light { background: #f5f5f7; color: #1d1d1f; }
.product-tile h3 { font-size: 40px; font-weight: 700; letter-spacing: -.02em; line-height: 1.1; }
.product-tile .tagline { font-size: 21px; color: #6e6e73; margin-top: 4px; font-weight: 400; }
.product-tile.dark .tagline { color: #a1a1a6; }
.product-tile .tile-ctas { margin-top: 14px; display: flex; gap: 20px; justify-content: center; }
.product-tile .tile-image {
  flex: 1; width: 100%; margin-top: 20px;
  display: flex; align-items: flex-end; justify-content: center;
}
.product-tile .tile-image .img-placeholder {
  width: 80%; height: 280px;
  border-radius: 12px;
  background: linear-gradient(135deg, #2a2a2e 0%, #1d1d1f 100%);
}
.product-tile.light .tile-image .img-placeholder {
  background: linear-gradient(135deg, #e8e8ed 0%, #d2d2d7 100%);
}
.product-tile .badge {
  position: absolute; top: 16px; left: 16px;
  background: #6e6e73; color: #fff; font-size: 11px; font-weight: 600;
  padding: 3px 10px; border-radius: 980px; text-transform: uppercase; letter-spacing: .02em;
}
.product-tile .price-info { font-size: 14px; color: #6e6e73; margin-top: 6px; }
.product-tile.dark .price-info { color: #a1a1a6; }

/* ===== Carousel ===== */
.carousel-section { position: relative; }
.carousel-track-wrapper {
  overflow: hidden;
  margin: 0 auto;
  max-width: 1024px;
  padding: 0 20px;
}
.carousel-track {
  display: flex;
  gap: 12px;
  transition: transform .5s cubic-bezier(.25,.1,.25,1);
  will-change: transform;
}
.carousel-card {
  flex: 0 0 280px;
  border-radius: 20px;
  overflow: hidden;
  background: #f5f5f7;
  position: relative;
}
.carousel-card .card-image {
  height: 220px;
  display: flex; align-items: center; justify-content: center;
  background: linear-gradient(135deg, #e8e8ed 0%, #d2d2d7 100%);
}
.carousel-card .card-image .img-placeholder {
  width: 60%; height: 140px;
  border-radius: 10px;
  background: linear-gradient(135deg, #c7c7cc 0%, #aeaeb2 100%);
}
.carousel-card .card-body {
  padding: 16px 20px 20px;
}
.carousel-card .card-badge {
  display: inline-block;
  font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: .02em;
  color: #6e6e73; margin-bottom: 6px;
}
.carousel-card h4 { font-size: 17px; font-weight: 600; line-height: 1.3; }
.carousel-card .card-tagline { font-size: 14px; color: #6e6e73; margin-top: 2px; }
.carousel-card .card-price { font-size: 14px; margin-top: 8px; }
.carousel-card .card-price .price { font-weight: 600; }
.carousel-card .card-price .monthly { color: #6e6e73; display: block; font-size: 12px; margin-top: 2px; }
.carousel-card .card-ctas { margin-top: 10px; display: flex; gap: 16px; }

/* Carousel arrows */
.carousel-arrow {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 36px; height: 36px;
  background: rgba(255,255,255,.9);
  border: 1px solid #d2d2d7;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 18px; color: #1d1d1f;
  z-index: 10;
  cursor: pointer;
  transition: background .2s;
  box-shadow: 0 1px 3px rgba(0,0,0,.1);
}
.carousel-arrow:hover { background: #fff; }
.carousel-arrow.left { left: max(10px, calc((100% - 1064px)/2)); }
.carousel-arrow.right { right: max(10px, calc((100% - 1064px)/2)); }
.carousel-arrow:disabled { opacity: .3; cursor: default; }
.carousel-arrow svg { width: 16px; height: 16px; }

/* ===== Product Icon Bar ===== */
.icon-bar {
  display: flex;
  justify-content: center;
  gap: 32px;
  padding: 30px 20px;
  border-bottom: 1px solid #d2d2d7;
  max-width: 1024px;
  margin: 0 auto;
  overflow-x: auto;
}
.icon-bar-item {
  display: flex; flex-direction: column; align-items: center; gap: 6px;
  text-decoration: none !important; color: #1d1d1f;
  font-size: 12px; min-width: 70px; text-align: center;
  transition: color .2s;
}
.icon-bar-item:hover { color: #0066cc; }
.icon-bar-item .icon-circle {
  width: 56px; height: 56px;
  border-radius: 50%;
  background: linear-gradient(135deg, #e8e8ed 0%, #d2d2d7 100%);
  display: flex; align-items: center; justify-content: center;
  font-size: 24px;
}

/* ===== Help Cards ===== */
.help-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 16px;
  max-width: 1024px;
  margin: 0 auto;
  padding: 0 20px;
}
.help-card {
  background: #f5f5f7;
  border-radius: 20px;
  padding: 28px;
  display: flex; flex-direction: column; gap: 8px;
}
.help-card h4 { font-size: 21px; font-weight: 600; }
.help-card p { font-size: 14px; color: #6e6e73; line-height: 1.4; }
.help-card .help-icon { font-size: 32px; margin-bottom: 4px; }

/* ===== Difference Cards ===== */
.diff-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 16px;
  max-width: 1024px;
  margin: 0 auto;
  padding: 0 20px;
}
.diff-card {
  background: #f5f5f7;
  border-radius: 20px;
  padding: 24px 20px;
  text-align: center;
}
.diff-card .diff-icon { font-size: 36px; margin-bottom: 8px; }
.diff-card h4 { font-size: 17px; font-weight: 600; }
.diff-card p { font-size: 13px; color: #6e6e73; margin-top: 4px; }

/* ===== Brand Collab ===== */
.brand-collab {
  text-align: center;
  padding: 60px 20px;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  color: #f5f5f7;
  border-radius: 20px;
  max-width: 1024px;
  margin: 0 auto;
}
.brand-collab h2 { font-size: 40px; font-weight: 700; letter-spacing: -.015em; }
.brand-collab p { font-size: 21px; color: #a1a1a6; margin-top: 8px; }

/* ===== Entertainment Tabs ===== */
.entertainment-section { max-width: 1024px; margin: 0 auto; padding: 0 20px; }
.ent-tabs {
  display: flex; justify-content: center; gap: 0;
  border-bottom: 1px solid #d2d2d7;
  margin-bottom: 30px;
}
.ent-tab {
  padding: 12px 24px;
  font-size: 17px; font-weight: 600; color: #6e6e73;
  border-bottom: 2px solid transparent;
  cursor: pointer;
  transition: all .2s;
  background: none; border-top: none; border-left: none; border-right: none;
}
.ent-tab.active { color: #1d1d1f; border-bottom-color: #1d1d1f; }
.ent-tab:hover { color: #1d1d1f; }
.ent-content { display: none; }
.ent-content.active { display: block; }
.ent-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}
.ent-card {
  border-radius: 16px;
  overflow: hidden;
  background: #f5f5f7;
  cursor: pointer;
  transition: transform .2s;
}
.ent-card:hover { transform: scale(1.02); }
.ent-card .ent-card-image {
  height: 180px;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  display: flex; align-items: flex-end; justify-content: flex-start;
  padding: 12px;
}
.ent-card .ent-card-title { font-size: 15px; font-weight: 600; color: #fff; }
.ent-card .ent-card-body { padding: 12px 14px; }
.ent-card .ent-card-label { font-size: 11px; text-transform: uppercase; color: #6e6e73; letter-spacing: .02em; }
.ent-card .ent-card-name { font-size: 14px; font-weight: 600; margin-top: 2px; }

/* ===== Quick Links ===== */
.quick-links {
  display: flex; justify-content: center; flex-wrap: wrap; gap: 12px;
  max-width: 1024px; margin: 0 auto; padding: 0 20px;
}
.quick-link-btn {
  padding: 10px 22px;
  border: 1px solid #d2d2d7;
  border-radius: 980px;
  font-size: 14px; color: #1d1d1f;
  transition: all .2s;
  background: #fff;
}
.quick-link-btn:hover { background: #f5f5f7; text-decoration: none; }

/* ===== Category Sticky Nav ===== */
.category-nav-wrapper {
  position: sticky; top: 48px;
  z-index: 100;
  background: rgba(255,255,255,.92);
  backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid #d2d2d7;
}
.category-nav {
  display: flex; justify-content: center; gap: 0;
  max-width: 1024px; margin: 0 auto; overflow-x: auto;
  padding: 0 20px;
}
.category-nav a {
  display: block;
  padding: 12px 16px;
  font-size: 14px; font-weight: 500; color: #6e6e73;
  white-space: nowrap;
  border-bottom: 2px solid transparent;
  transition: all .2s;
  text-decoration: none !important;
}
.category-nav a.active, .category-nav a:hover {
  color: #1d1d1f; border-bottom-color: #1d1d1f;
}

/* ===== Category Hero ===== */
.category-hero {
  text-align: center;
  padding: 80px 20px 60px;
  background: #f5f5f7;
}
.category-hero h1 {
  font-size: 56px; font-weight: 700; letter-spacing: -.02em; line-height: 1.05;
}
.category-hero p {
  font-size: 21px; color: #6e6e73; margin-top: 8px;
}

/* ===== Shopping Guide Cards ===== */
.guide-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 16px;
  max-width: 1024px; margin: 0 auto; padding: 0 20px;
}
.guide-card {
  background: #f5f5f7;
  border-radius: 20px;
  padding: 28px;
  text-align: center;
}
.guide-card h4 { font-size: 21px; font-weight: 600; }
.guide-card p { font-size: 14px; color: #6e6e73; margin-top: 6px; line-height: 1.4; }
.guide-card .guide-icon { font-size: 36px; margin-bottom: 8px; }

/* ===== Experience Section ===== */
.experience-banner {
  max-width: 1024px; margin: 0 auto; padding: 0 20px;
}
.experience-inner {
  background: #000; color: #f5f5f7;
  border-radius: 20px;
  padding: 60px 40px;
  text-align: center;
}
.experience-inner h3 { font-size: 40px; font-weight: 700; }
.experience-inner p { font-size: 21px; color: #a1a1a6; margin-top: 8px; }

/* ===== Footer ===== */
.site-footer {
  background: #f5f5f7;
  padding: 30px 0 20px;
  font-size: 12px;
  color: #6e6e73;
  border-top: 1px solid #d2d2d7;
}
.footer-inner {
  max-width: 1024px; margin: 0 auto; padding: 0 20px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 24px;
  padding-bottom: 20px;
  border-bottom: 1px solid #d2d2d7;
}
.footer-col h5 {
  font-size: 12px; font-weight: 600; color: #1d1d1f;
  margin-bottom: 10px;
}
.footer-col a { display: block; color: #6e6e73; font-size: 12px; line-height: 2; }
.footer-col a:hover { color: #1d1d1f; text-decoration: underline; }
.footer-legal { padding-top: 16px; line-height: 1.7; }
.footer-legal p { margin-bottom: 8px; }

/* Footer accordion (mobile) */
.footer-col .accordion-toggle {
  display: none;
  width: 100%;
  text-align: left;
  padding: 10px 0;
  font-size: 12px; font-weight: 600; color: #1d1d1f;
  border-bottom: 1px solid #d2d2d7;
  cursor: pointer;
  background: none;
}
.footer-col .accordion-toggle::after { content: '+'; float: right; font-size: 14px; }
.footer-col.open .accordion-toggle::after { content: '−'; }

/* ===== Responsive ===== */
@media (max-width: 768px) {
  .top-nav .nav-links { gap: 14px; }
  .top-nav .nav-links a { font-size: 11px; }
  .hero h1, .category-hero h1 { font-size: 36px; }
  .hero p, .category-hero p { font-size: 19px; }
  .section-header h2 { font-size: 32px; }
  .section-header p { font-size: 17px; }
  .product-grid { grid-template-columns: 1fr; }
  .product-tile { min-height: 420px; }
  .product-tile h3 { font-size: 28px; }
  .product-tile .tagline { font-size: 17px; }
  .carousel-card { flex: 0 0 240px; }
  .ent-grid { grid-template-columns: repeat(2, 1fr); }
  .icon-bar { justify-content: flex-start; gap: 20px; padding-left: 20px; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-col .accordion-toggle { display: block; }
  .footer-col .footer-links { display: none; }
  .footer-col.open .footer-links { display: block; }
  .brand-collab h2 { font-size: 28px; }
  .diff-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 480px) {
  .ent-grid { grid-template-columns: 1fr; }
  .help-grid { grid-template-columns: 1fr; }
  .diff-grid { grid-template-columns: 1fr; }
  .guide-grid { grid-template-columns: 1fr; }
}

