/* ===== Product Grid (Homepage) ===== */
.product-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  max-width: 1024px;
  margin: 0 auto;
  padding: 0 20px;
}
.product-tile {
  position: relative;
  border-radius: 20px;
  overflow: hidden;
  text-align: center;
  padding: 44px 30px 0;
  min-height: 500px;
  display: flex;
  flex-direction: column;
  align-items: center;
}
