/* ===== Carousel ===== */
.carousel-section { position: relative; }
.carousel-track-wrapper {
  overflow: hidden;
  margin: 0 auto;
  max-width: 1024px;
  padding: 0 20px;
}
.carousel-track {
  display: flex;
  gap: 12px;
  transition: transform .5s cubic-bezier(.25,.1,.25,1);
  will-change: transform;
}
.carousel-card {
  flex: 0 0 280px;
  border-radius: 20px;
  overflow: hidden;
  background: #f5f5f7;
  position: relative;
}
.carousel-card .card-image {
  height: 220px;
